"""Dokkai N3 v2 — paket 12–20. Susunan: 4 短文 + 中文 (3 soal) + 長文 (4 soal) + 情報検索 (2 soal) = 13."""
T, C, L, J = "Teks pendek (内容理解・短文)", "Teks menengah (内容理解・中文)", "Teks panjang (内容理解・長文)", "Mencari informasi (情報検索)"


def tbl(head, rows):
    h = "".join(f"<th>{x}</th>" for x in head)
    b = "".join("<tr>" + "".join(f"<td>{x}</td>" for x in r) + "</tr>" for r in rows)
    return f"<table class='jx-table'><tr>{h}</tr>{b}</table>"


